-- =====================================================================
-- SmarterVote.ca — expansion seed: races
--
-- One row per (municipality, race) from the staged roster. Race slugs are
-- {municipality-slug}-{slugify(raw race label)} — computed from the RAW
-- staged label, so labels like 'Mayor' vs 'Mayor ' merge into one race.
--
-- race_type: 'trustee' in label -> school_board; 'ward' in label ->
--   council_ward; label exactly 'Mayor' (ignoring staged '(Acclaimed)' /
--   '- Acclaimed' suffixes) -> mayor; otherwise council_at_large.
--   BC electoral districts -> provincial_district.
-- seats: parsed from 'N to be elected' / 'Two to be elected' phrasing in
--   the label (digits + One..Seven supported); defaults to 1.
-- is_acclaimed: true only if EVERY staged row for the race has
--   acclaimed=true (staged nulls count as not acclaimed).
-- sort_order: mayor 0, council 10+, school board 20+, provincial 30+.
--
-- Run AFTER 24 (needs the widened race_type check) and 25.
-- Idempotent: on conflict (municipality_id, slug) do nothing.
-- =====================================================================

begin;

insert into races
    (municipality_id, name, slug, race_type, seats, is_acclaimed, sort_order)
select m.id, v.name, v.slug, v.race_type, v.seats, v.is_acclaimed, v.sort_order
from (values
